class Solution:
    def coverWindow(self, s: str, t: str) -> str:
        n = len(s)
        base = {}
        for c in t:
            base[c] = base.get(c, 0) + 1
        best_len, best_start = n + 1, 0
        for i in range(n):
            need, missing = dict(base), len(t)
            for j in range(i, min(n, i + best_len - 1)):
                if need.get(s[j], 0) > 0:
                    missing -= 1
                need[s[j]] = need.get(s[j], 0) - 1
                if missing == 0:
                    best_len, best_start = j - i + 1, i
                    break
        return s[best_start:best_start + best_len] if best_len <= n else ""

