class Solution {
    public String coverWindow(String s, String t) {
        int n = s.length(), bestLen = n + 1, bestStart = 0;
        int[] base = new int[128];
        for (char c : t.toCharArray()) base[c]++;
        for (int i = 0; i < n; i++) {
            int[] need = base.clone();
            int missing = t.length();
            for (int j = i; j < n && j - i + 1 < bestLen; j++) {
                if (need[s.charAt(j)]-- > 0) missing--;
                if (missing == 0) { bestLen = j - i + 1; bestStart = i; break; }
            }
        }
        return bestLen <= n ? s.substring(bestStart, bestStart + bestLen) : "";
    }
}

