        for c in t:
            need[c] = need.get(c, 0) + 1
        missing, left = len(t), 0
        best_len, best_start = len(s) + 1, 0
        for i, c in enumerate(s):
            if need.get(c, 0) > 0:
                missing -= 1
            need[c] = need.get(c, 0) - 1
            while missing == 0:
                if i - left + 1 < best_len:
                    best_len, best_start = i - left + 1, left
                need[s[left]] += 1
                if need[s[left]] > 0:
                    missing += 1
                left += 1
        return s[best_start:best_start + best_len] if best_len <= len(s) else ""

