            if (need[s.charAt(i)]-- > 0) missing--;
            while (missing == 0) {
                if (i - left + 1 < bestLen) { bestLen = i - left + 1; bestStart = left; }
                if (++need[s.charAt(left++)] > 0) missing++;
            }
        }
        return bestLen <= n ? s.substring(bestStart, bestStart + bestLen) : "";
    }
}

